function mergeKnown(base,input){for(const k of Object.keys(base)){if(!(k in input))continue;if(Array.isArray(base[k])){if(Array.isArray(input[k]))base[k]=input[k];}else if(base[k]&&typeof base[k]==='object'){if(input[k]&&typeof input[k]==='object'&&!Array.isArray(input[k]))mergeKnown(base[k],input[k]);}else if(typeof input[k]===typeof base[k])base[k]=input[k];}return base;}
function loadStateV1(){try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){const data=JSON.parse(raw);if(data.version!==1||!PRESETS[data.preset])return defaultState();const state=mergeKnown(defaultState(),data);for(const k of TRAIT_KEYS)state.personality[k]=Math.max(0,Math.min(100,Number(state.personality[k])||0));if(!GOALS[state.sales.goal])state.sales.goal='book_demo';state.chat.busy=false;state.chat.open=false;state.chat.messages=state.chat.messages.filter(m=>m&&typeof m.text==='string'&&['user','assistant','roi'].includes(m.role));state.objections=state.objections.filter(o=>o&&typeof o.objection==='string');return state;}}catch(e){storageAvailable=false;}return defaultState();}
let salesman=loadState();
