/* Render functions */
function selectField(label,path,options){const val=pathGet(salesman,path);return `<div class="field"><label for="${path}">${label}</label><select id="${path}" data-bind="${path}">${options.map(x=>{const [v,t]=Array.isArray(x)?x:[x,title(x)];return `<option value="${esc(v)}" ${val===v?'selected':''}>${esc(t)}</option>`;}).join('')}</select></div>`;}
function textField(label,path,multi=false){const val=pathGet(salesman,path);const text=Array.isArray(val)?val.join('\n'):val;return `<div class="field"><label for="${path}">${label}</label>${multi?`<textarea id="${path}" data-bind="${path}" ${Array.isArray(val)?'data-array="true"':''}>${esc(text)}</textarea>`:`<input id="${path}" data-bind="${path}" value="${esc(text)}">`}</div>`;}
function imageKey(preset=salesman.preset,gender=salesman.appearance.gender){return personaImageMap[preset]?.[gender]||'alex';}
/* Natural language parser */
function parseDescription(text){const t=text.toLowerCase();let key=salesman.preset;
 if(/華爾街|wolf of wall street|激情銷售|強勢成交|超級業務|\bcloser\b|high[- ]energy sales/.test(t))key='wolf';
 else if(/analytical|分析|數據|data[- ]driven|冷靜/.test(t))key='strategist';
 else if(/luxury|高端|精品|奢華/.test(t))key='luxury';
 else if(/warm|溫暖|empathetic|同理|consultative|顧問/.test(t))key='advisor';
 else if(/professional|專業|沉穩|calm|expert/.test(t))key='expert';
 else if(/energetic|激情|高能量|陽光|friendly/.test(t))key='energetic';
 applyPreset(key);const p=salesman.personality;
 const hasPositive=(words)=>words.some(word=>{const re=new RegExp(word,'gi');let m;while((m=re.exec(t))){const before=t.slice(Math.max(0,m.index-24),m.index);if(!/(?:not|never|no|without|don't|do not|不|不要|避免)\s*(?:be\s+|very\s+|too\s+|要|太|過於|非常)?$/.test(before))return true;}return false;});
 if(hasPositive(['confident','自信']))p.confidence=Math.max(95,p.confidence);
 if(hasPositive(['aggressive','強勢','積極']))p.aggressiveness=Math.max(82,p.aggressiveness);
 if(hasPositive(['energetic','激情','高能量']))p.energy=Math.max(95,p.energy);
 if(hasPositive(['warm','溫暖','同理']))p.empathy=Math.max(92,p.empathy);
 if(/never pressure|never pressures|without pressure|no pressure|not aggressive|不強迫|不施壓|不要強勢|(?:不|別|避免|絕不).{0,6}施壓/.test(t)){p.aggressiveness=18;p.urgency=15;p.patience=Math.max(90,p.patience);salesman.sales.rules=salesman.sales.rules.filter(r=>r!=='urgency');}
 if(/\bfemale\b|女/.test(t))salesman.appearance.gender='female';else if(/\bmale\b|男/.test(t))salesman.appearance.gender='male';
 if(salesman.appearance.gender!==PRESETS[key].gender){salesman.identity.name=salesman.appearance.gender==='female'?'Emma Carter':'Marcus Reed';salesman.voice.name=salesman.appearance.gender==='female'?(key==='energetic'?'Emily':'Sophia'):'Marcus';}
 if(/roi/.test(t)&&!salesman.sales.rules.includes('roi'))salesman.sales.rules.push('roi');if(/book\s*(a\s*)?demo|預約\s*demo/i.test(t)){salesman.sales.goal='book_demo';salesman.sales.cta=GOALS.book_demo;}
 if(/white shirt|白襯衫/.test(t))salesman.appearance.outfit='white_shirt';if(/fast|快速/.test(t))salesman.voice.speed='fast';if(/slow|緩慢|慢速/.test(t))salesman.voice.speed='slow';
 const age=t.match(/(?:age[d]?\s*|around\s*|約\s*)(\d{2})/i)||t.match(/(\d{2})\s*(?:歲|years old)/);if(age)salesman.appearance.age=Math.max(25,Math.min(55,Number(age[1])));
 return key;
}
