/* V2 State migration: keep V1 training and saved work, add shared preview state. */
function defaultState(){const s=defaultStateV1();s.revision=2;s.product=clone(DEFAULT_PRODUCT_ZH);s.objections=clone(DEFAULT_OBJECTIONS_ZH);s.sales.cta=GOALS.book_demo;s.appearance.variant=0;s.meta.previewMode='avatar';s.avatar={state:'idle',transcript:'',subtitle:'先不要急著看產品。我先問你一個問題。你現在這個問題，每個月到底正在花你多少錢？'};return s;}
function loadState(){const s=loadStateV1();let old;try{old=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');}catch{}if(old&&!old.revision){s.meta.generated=false;if(old.product?.description==='AI customer service platform that helps companies automate repetitive support questions.')s.product=clone(DEFAULT_PRODUCT_ZH);if(old.objections?.[0]?.objection==="It's too expensive.")s.objections=clone(DEFAULT_OBJECTIONS_ZH);if(['Book a Demo','Purchase','Leave Contact','Request Quote','Start Free Trial','Call Sales','Talk to Human'].includes(s.sales.cta))s.sales.cta=GOALS[s.sales.goal];}s.revision=2;s.meta.previewMode=['avatar','chat'].includes(s.meta.previewMode)?s.meta.previewMode:'avatar';s.avatar.state='idle';s.avatar.transcript='';s.avatar.subtitle=s.avatar.subtitle||PRESETS[s.preset].opening;s.appearance.variant=[0,1].includes(s.appearance.variant)?s.appearance.variant:0;s.chat.busy=false;s.chat.open=false;return s;}
function persist(){try{const snapshot=clone(salesman);snapshot.chat.busy=false;snapshot.chat.open=false;snapshot.avatar.state='idle';snapshot.avatar.transcript='';localStorage.setItem(STORAGE_KEY,JSON.stringify(snapshot));storageAvailable=true;$('#save-status').textContent='● 已儲存在此裝置';return true;}catch{storageAvailable=false;$('#save-status').textContent='無法儲存在此裝置';return false;}}
function scheduleSave(){clearTimeout(saveTimer);$('#save-status').textContent='儲存中…';saveTimer=setTimeout(persist,250);}
function markChanged(){salesman.meta.generated=false;renderPreview();scheduleSave();}
function priceLabel(){return numberPrice()===null?'專屬報價':money(numberPrice());}
function firstName(){return salesman.identity.name.trim().split(/\s+/)[0]||'Alex';}
/* Generated offline image sheets: two distinct portraits per persona. */
function portraitSpec(key=salesman.preset,variant=salesman.appearance.variant){const source=PORTRAIT_SHEETS[key];return {source:source||IMAGE_ASSETS[imageKey(key,PRESETS[key].gender)],panel:source?(variant===1?1:0):0,split:!!source};}
function currentImage(){return portraitSpec().source;}
function portraitHTML(key=salesman.preset,variant=salesman.appearance.variant,alt='原創虛構 AI 業務形象'){const p=portraitSpec(key,variant);return `<div class="portrait-thumb" style="--portrait-width:${p.split?'200%':'100%'};--portrait-left:${p.panel===1?'-100%':'0%'}"><img class="portrait-strip" src="${p.source}" alt="${esc(alt)}" decoding="async"></div>`;}
function bestVariant(appearance=salesman.appearance,key=salesman.preset){const weights={gender:8,style:3,outfit:4,environment:3,energy:2};const list=VARIANT_META[key];let best=0,score=-Infinity;list.forEach((v,i)=>{let n=-Math.abs(v.age-appearance.age)/8;for(const [field,weight] of Object.entries(weights))if(v[field]===appearance[field])n+=weight;if(n>score){score=n;best=i;}});return best;}
function mockGenerateImage(){const chosen=bestVariant();salesman.appearance.variant=chosen;return portraitSpec(salesman.preset,chosen);}
function renderVariants(){const host=$('#appearance-variants');if(!host)return;host.innerHTML=VARIANT_META[salesman.preset].map((v,i)=>`<button class="variant-choice ${i===salesman.appearance.variant?'active':''}" data-variant="${i}" aria-pressed="${i===salesman.appearance.variant}">${portraitHTML(salesman.preset,i,v.label)}<span>${esc(v.label)}</span></button>`).join('');}
