function renderImports(){$('#website-import-result').innerHTML=salesman.knowledge.imported?'<div class="import-result">✓ 找到 23 個頁面<br>✓ 整理出 126 個產品資訊<br><small>範例知識 · 模擬匯入結果</small></div>':'';$('#upload-list').innerHTML=salesman.knowledge.files.map((f,i)=>`<div class="upload-item"><div>${esc(f.name)}<div><small>模擬擷取 ${Number(f.facts)||0} 項知識</small></div></div><button class="icon-btn" data-remove-file="${i}" aria-label="移除 ${esc(f.name)}">×</button></div>`).join('');}
