function openingLine(){if(salesman.product.name==='Customer Service AI')return PRESETS[salesman.preset].opening;const name=salesman.product.name||'這個產品';const lines={wolf:`先不要急著看 ${name}。我先問你一件事：你現在這個問題，每個月到底正在花你多少錢？`,advisor:`在推薦 ${name} 前，我想先了解：你最希望改善什麼？怎麼樣才算真的適合你？`,strategist:`我們先定義評估 ${name} 的指標。你希望改善成本、時間，還是其他可量化的結果？`,luxury:`關於 ${name}，你最重視什麼樣的體驗與標準？讓我先了解你的偏好。`,energetic:`一起看看 ${name} 能幫上什麼忙！你最想讓哪件事變得更輕鬆？`,expert:`評估 ${name} 前，我建議先釐清目前的做法，以及導入必須滿足的條件。你想先從哪裡開始？`};return lines[salesman.preset];}
function readiness(){return [{name:'人格已設定',done:!!salesman.identity.name.trim()&&!!PRESETS[salesman.preset],weight:20},{name:'產品知識已加入',done:!!salesman.product.name.trim()&&!!salesman.product.description.trim(),weight:25},{name:'成交目標已設定',done:!!GOALS[salesman.sales.goal]&&!!salesman.sales.cta.trim(),weight:15},{name:'異議處理已準備',done:salesman.objections.some(o=>o.objection.trim()&&o.strategy.trim()),weight:20},{name:'聲音已設定',done:!!salesman.voice.name&&['slow','normal','fast'].includes(salesman.voice.speed),weight:10},{name:'預覽已準備',done:!!currentImage(),weight:10}];}
function readinessScore(){return readiness().reduce((sum,item)=>sum+(item.done?item.weight:0),0);}
function trainingStatus(){return salesman.meta.generated&&readinessScore()===100?'已準備好開始銷售':'草稿';}
